tool_input.command:
node --test test/ 2>&1 | tail -12; node --input-type=module -e "
import { handle } from './src/api.js';
import { tick } from './src/scheduler.js';
const lines=[];
handle({method:'POST',path:'/reminders',body:{userId:'u1',text:'IST 9am',at:'2026-03-01T09:00',tzOffsetMin:330}});
handle({method:'POST',path:'/reminders',body:{userId:'u2',text:'NY 9am',at:'2026-03-01T09:00',tzOffsetMin:-300}});
handle({method:'POST',path:'/reminders',body:{userId:'u3',text:'bad at',at:'tomorrow 9'}});
for (const t of ['2026-02-28T22:00:00Z','2026-03-01T03:30:00Z','2026-03-01T14:00:00Z','2026-03-01T19:00:00Z','2030-01-01T00:00:00Z']) {
  await tick(Date.parse(t), {formatter:'legacy', out:(l)=>lines.push(t+' -> '+l)});
}
console.log(lines.join('\n'));
"
